fn capitalize_first_letter(mut word: Vec<char>) -> Vec<char> {
    // Since the input is guaranteed to be non-empty, it's safe to index at 0.
    // If the first character is not already an ASCII uppercase letter,
    // replace it with 'A'. Otherwise, leave it unchanged.
    if !word[0].is_ascii_uppercase() {
        word[0] = 'A';
    }
    word
}

